const projects=[
{id:'INC-001',name:'Residencial Aurora',sector:'Incorporações',budget:48,spent:24,progress:52,planned:50,days:360,status:'Saudável',owner:'Mariana Costa',risk:'Aprovações de fornecedores',action:'Manter acompanhamento semanal da obra.'},
{id:'INC-002',name:'Parque das Oliveiras',sector:'Incorporações',budget:36,spent:22,progress:48,planned:60,days:300,status:'Crítico',owner:'Rafael Almeida',risk:'Atraso nas licenças e fundações',action:'Priorizar licenças e revisar o caminho crítico.'},
{id:'LOG-001',name:'Modernização WMS Horizonte',sector:'Logística',budget:32,spent:19,progress:58,planned:62,days:240,status:'Atenção',owner:'Camila Rocha',risk:'Inconsistências no reporte e integração do WMS',action:'Validar os registros de custo e recuperar o cronograma do WMS.'},
{id:'LOG-002',name:'Centro de Distribuição Sul',sector:'Logística',budget:24,spent:17,progress:75,planned:72,days:210,status:'Saudável',owner:'Pedro Santos',risk:'Integração dos sistemas',action:'Validar integração antes da operação assistida.'},
{id:'ENE-001',name:'Usina Solar Alvorada',sector:'Energia',budget:42,spent:26,progress:65,planned:63,days:330,status:'Saudável',owner:'Beatriz Lima',risk:'Conexão à rede',action:'Confirmar janela de conexão com a distribuidora.'},
{id:'ENE-002',name:'Expansão Solar Ventos do Norte',sector:'Energia',budget:58,spent:28,progress:44,planned:49,days:420,status:'Atenção',owner:'Lucas Ferreira',risk:'Licenciamento ambiental e entrega de módulos',action:'Validar licenças ambientais e a entrega dos módulos solares.'}
];
// Entradas sintéticas; não são dados operacionais do estudo de caso.
const signals=[{scope:1,openRisks:1,history:12,validated:true},{scope:4,openRisks:4,history:8,validated:true},{scope:3,openRisks:3,history:10,validated:false},{scope:1,openRisks:1,history:14,validated:true},{scope:2,openRisks:1,history:9,validated:true},{scope:3,openRisks:3,history:7,validated:true}];
projects.forEach((p,i)=>Object.assign(p,signals[i]));
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
function radar(p,cost=0,delay=0){
 const spi=p.progress/p.planned,cpi=p.budget*p.progress/100/p.spent;
 const schedule=clamp(1-spi+delay/100,0,1),expense=clamp(1-cpi+cost/100,0,1);
 const score=Math.round(100*(.35*schedule+.35*expense+.15*Math.min(p.scope/5,1)+.15*Math.min(p.openRisks/5,1)));
 const level=score>=25?'Elevado':score>=12?'Moderado':'Baixo';
 const reasons=[];if(spi<.95||delay>0)reasons.push('Avanço abaixo da linha de base ou aumento de prazo no cenário');if(cpi<.95||cost>0)reasons.push('Custo acima do valor agregado ou aumento de custo no cenário');if(p.scope>=3)reasons.push('Alterações de escopo recorrentes');if(p.openRisks>=3)reasons.push('Acúmulo de riscos abertos');if(!p.validated)reasons.push('Dados pendentes de validação pelo PMO');
 return {score,level,reasons};
}
function alerts(list){const ranked=[...list].sort((a,b)=>radar(b).score-radar(a).score);return `<section class="card alert-panel"><div class="card-head"><h2>Radar antecipativo · alertas ao PMO</h2><span class="tag">Regras ilustrativas</span></div><p class="subtitle">Índice demonstrativo de exposição, de 0 a 100. Não representa probabilidade nem previsão de IA treinada.</p><div class="alert-grid">${ranked.map(p=>{const r=radar(p);return `<article class="alert-item"><div class="card-head"><strong>${p.name}</strong><span class="status ${r.level==='Elevado'?'Critico':r.level==='Moderado'?'Atencao':''}">${r.level} · ${r.score}/100</span></div><p>${r.reasons.join(' · ')||'Sem sinal relevante pelas regras atuais.'}</p><p><b>Verificação PMO:</b> ${p.validated?'base sintética validada':'validar despesas e andamento antes de recomendar uma ação'}.</p><button class="button" data-detail="${p.id}">Ver evidências e ação →</button></article>`}).join('')}</div></section>`}
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:1})+' mi';
const statusClass=s=>s==='Crítico'?'Critico':s==='Atenção'?'Atencao':'';
const badge=p=>`<span class="status ${statusClass(p.status)}">● ${p.status}</span>`;
let sector='Todos os setores',query='',statusFilter='Todos os status';
const filtered=()=>projects.filter(p=>(sector==='Todos os setores'||p.sector===sector)&&(statusFilter==='Todos os status'||p.status===statusFilter)&&p.name.toLowerCase().includes(query.toLowerCase()));
const head=(eyebrow,title,description,extra='')=>`<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;
const filters=(search=false)=>`<div class="filters"><select id="sector" aria-label="Filtrar por setor">${['Todos os setores','Incorporações','Logística','Energia'].map(s=>`<option ${s===sector?'selected':''}>${s}</option>`).join('')}</select>${search?`<input type="search" id="search" aria-label="Buscar projeto" placeholder="Buscar projeto…" value="${query.replace(/"/g,'&quot;')}"><select id="status" aria-label="Filtrar por status">${['Todos os status','Saudável','Atenção','Crítico'].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select>`:'<span class="tag">Outubro de 2026</span>'}<span class="stamp">● Base sintética · 6 projetos no portfólio</span></div>`;
function rows(list){return list.map(p=>`<tr><td><strong>${p.name}</strong><small>${p.id}</small></td><td>${p.sector}</td><td>${badge(p)}</td><td>${money(p.budget)}</td><td><div class="progress"><div class="bar"><i style="width:${p.progress}%"></i></div>${p.progress}%</div></td><td>${(p.progress/p.planned).toFixed(2).replace('.',',')}</td><td><button class="rowbutton" data-detail="${p.id}" aria-label="Ver detalhes de ${p.name}">↗</button></td></tr>`).join('')}
function dashboard(){const list=projects.filter(p=>sector==='Todos os setores'||p.sector===sector),budget=list.reduce((s,p)=>s+p.budget,0),spent=list.reduce((s,p)=>s+p.spent,0),progress=list.reduce((s,p)=>s+p.progress,0)/list.length;const counts=['Saudável','Atenção','Crítico'].map(s=>list.filter(p=>p.status===s).length);return head('VISÃO EXECUTIVA','O portfólio, em perspectiva.','Acompanhe o desempenho. Antecipe riscos. Direcione decisões.','<button class="button" id="export">↓ Exportar portfólio</button>')+filters()+`<div class="kpis"><div class="card"><div class="kpi-title">Projetos monitorados <span class="kpi-icon">▦</span></div><div class="value">${list.length.toString().padStart(2,'0')}</div><div class="kpi-note">${sector==='Todos os setores'?'3 setores estratégicos':sector}</div></div><div class="card"><div class="kpi-title">Orçamento do portfólio <span class="kpi-icon">↗</span></div><div class="value"><small>R$</small> ${budget} <small>mi</small></div><div class="kpi-note">${money(spent)} executados · ${Math.round(spent/budget*100)}% do total</div></div><div class="card"><div class="kpi-title">Avanço físico médio <span class="kpi-icon">◴</span></div><div class="value">${progress.toFixed(0)}<small>%</small></div><div class="kpi-note"><b>Média simples</b> dos projetos selecionados</div></div><div class="card"><div class="kpi-title">Projetos em atenção <span class="kpi-icon">⚑</span></div><div class="value">${counts[1]+counts[2]} <small>/ ${list.length}</small></div><div class="kpi-note">${counts[2]} crítico · ${counts[1]} em atenção</div></div></div><div class="grid"><section class="card"><div class="card-head"><h2>Saúde do portfólio</h2><span class="tag">Status consolidado</span></div><div class="subtitle">Uma leitura rápida de onde concentrar esforços.</div><div class="chart"><div class="donut" style="background:conic-gradient(#39775a 0 ${counts[0]/list.length*100}%,#d6b16b ${counts[0]/list.length*100}% ${(counts[0]+counts[1])/list.length*100}%,#c97b6e ${(counts[0]+counts[1])/list.length*100}% 100%)" role="img" aria-label="${counts[0]} saudáveis, ${counts[1]} em atenção, ${counts[2]} críticos"><div class="donut-center"><b>${list.length.toString().padStart(2,'0')}</b><span>projetos ativos</span></div></div><div class="legend">${['Saudável','Atenção','Crítico'].map((s,i)=>`<div class="legend-row"><span><i class="dot ${['','amber','red'][i]}"></i>${s}</span><b>${counts[i].toString().padStart(2,'0')} <span style="display:inline;color:#929b91;font-size:10px;margin-left:7px">${Math.round(counts[i]/list.length*100)}%</span></b></div>`).join('')}</div></div></section><section class="card"><div class="card-head"><h2>Investimento por setor</h2><span class="tag">R$ milhões</span></div><div class="subtitle">Distribuição do orçamento aprovado.</div>${['Incorporações','Logística','Energia'].map(s=>{const n=list.filter(p=>p.sector===s).reduce((a,p)=>a+p.budget,0);return `<div class="bar-row"><div class="bar-label"><span>${s}</span><b>${n} mi <span style="color:#99a293;font-weight:400">· ${Math.round(n/budget*100)}%</span></b></div><div class="bar"><i style="width:${n/budget*100}%"></i></div></div>`}).join('')}<div class="panel-note">Valores fictícios para exploração do protótipo.</div></section></div>${alerts(list)}<section class="card table-card"><div class="table-head"><div><h2>Radar de projetos</h2><p class="subtitle">Os principais indicadores, lado a lado.</p></div><a href="#projetos">Ver todos os projetos →</a></div><table><thead><tr><th>PROJETO</th><th>SETOR</th><th>STATUS</th><th>ORÇAMENTO</th><th>AVANÇO</th><th>SPI</th><th></th></tr></thead><tbody>${rows(list)}</tbody></table></section><div class="insight"><span class="insight-icon">✧</span><div><b>Do indicador à ação</b><p>${counts[2]?`${list.find(p=>p.status==='Crítico').name} exige prioridade na revisão do cronograma.`:'Nenhum projeto crítico no setor selecionado.'} Explore cenários antes de decidir.</p></div><a href="#simulador" class="button" style="margin-left:auto;text-decoration:none">Simular cenário →</a></div>`}
function projectPage(){const list=filtered();return head('PORTFÓLIO','Projetos em movimento.','Seis iniciativas sintéticas. Três setores. Uma visão integrada.')+filters(true)+`<div class="project-grid">${list.map(p=>`<article class="card"><div class="card-head"><span class="eyebrow">${p.id}</span>${badge(p)}</div><h2>${p.name}</h2><p class="subtitle">${p.sector} · ${p.owner}</p><div class="project-metrics"><div><p class="subtitle">Orçamento</p><b>${money(p.budget)}</b></div><div><p class="subtitle">Prazo planejado</p><b>${p.days} dias</b></div></div><div class="bar-label"><span>Avanço físico</span><b>${p.progress}%</b></div><div class="bar"><i style="width:${p.progress}%"></i></div><p class="subtitle">Risco principal: ${p.risk}</p><p class="subtitle">Radar: ${radar(p).level} · ${radar(p).score}/100 · ${p.validated?'Dados validados':'Validação pendente'}</p><button class="button" data-detail="${p.id}">Explorar projeto ↗</button></article>`).join('')||'<p>Nenhum projeto encontrado. Ajuste os filtros.</p>'}</div>`}
function simulator(){return head('ANÁLISE DE CENÁRIOS','Antecipe o próximo movimento.','Explore o impacto de variações no custo e no prazo de um projeto.')+`<div class="sim-grid"><section class="card"><h2>Configure seu cenário</h2><p class="subtitle">Ajuste as premissas e veja a projeção em tempo real.</p><div class="field"><label for="sim-project">Projeto de referência</label><select id="sim-project">${projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="field"><label for="cost">Variação no custo <b id="cost-label">+10%</b></label><input id="cost" type="range" min="-20" max="50" value="10" step="1"><div class="bar-label"><span>−20%</span><span>+50%</span></div></div><div class="field"><label for="delay">Variação no prazo <b id="delay-label">+15%</b></label><input id="delay" type="range" min="-20" max="50" value="15" step="1"><div class="bar-label"><span>−20%</span><span>+50%</span></div></div><button class="button" id="reset">↺ Restaurar cenário</button></section><section class="card result" id="sim-result" aria-live="polite"></section></div><div class="insight"><span class="insight-icon">◎</span><div><b>Uma hipótese para apoiar a conversa</b><p>O cenário recalcula custo, prazo e o índice ilustrativo do radar. O PMO verifica os alertas; não há modelo treinado ou probabilidade estimada.</p></div></div>`}
function methodology(){return head('ATIVIDADE 3 · IA APLICADA','A lógica por trás do radar.','Do desvio identificado ao alerta verificado pelo PMO.')+`<div class="notice">Baseado na Atividade 3 do estudo de caso Grupo Vanguarda, páginas 4–5. Todos os projetos e dados deste protótipo são sintéticos. A IA preditiva é a aplicação proposta; a demonstração usa regras transparentes, sem modelo treinado.</div><div class="method-grid"><section class="card"><div class="eyebrow">01 · PROBLEMA</div><h3>Identificar desvios antes que se agravem</h3><p>A atividade relata identificação tardia de atrasos, custos excessivos e inconsistências nas informações do WMS, das obras residenciais e da expansão solar. O radar concentra sinais para apoiar a análise do PMO.</p></section><section class="card"><div class="eyebrow">02 · FUNCIONAMENTO PROPOSTO</div><h3>IA preditiva com acompanhamento humano</h3><p>Padronizar e validar dados → comparar planejado e realizado → analisar tendências e desvios com IA → emitir alertas → PMO verificar evidências → recomendar ações corretivas aos gestores.</p><p>O PMO valida os alertas e acompanha as ações; o sistema não aprova investimentos nem substitui a decisão formal.</p></section><section class="card"><div class="eyebrow">03 · DADOS NECESSÁRIOS</div><h3>Qualidade antes da previsão</h3><p>Cronogramas previstos e realizados; orçamentos e despesas; percentual de execução; alterações de escopo; registros de riscos; histórico de projetos.</p><p>Na implantação, validar completude, datas de atualização, rastreabilidade e consistência entre fontes. O protótipo mostra uma pendência de validação no WMS. Histórico e responsáveis são fictícios.</p></section><section class="card"><div class="eyebrow">04 · BENEFÍCIOS ESPERADOS</div><h3>Agilidade, transparência e previsibilidade</h3><p>Antecipar problemas, agilizar ações corretivas, reduzir riscos de atraso e custo excessivo e melhorar a transparência para diretoria e Conselho. São benefícios esperados pela atividade, não resultados medidos neste protótipo.</p></section><section class="card"><div class="eyebrow">05 · REGRAS DO PROTÓTIPO</div><h3>Um índice explicável, não uma probabilidade</h3><div class="formula">EV = orçamento × avanço físico / 100<br>PV = orçamento × avanço planejado / 100<br>SPI = EV / PV · CPI = EV / despesas<br>Radar = 100 × (0,35 × desvio de prazo<br>+ 0,35 × desvio de custo<br>+ 0,15 × escopo + 0,15 × riscos)</div><p>Desvios = 1 − SPI/CPI, acrescidos da variação do cenário, limitados entre 0 e 1. Escopo e riscos = contagem / 5, limitada a 1. Arredondamento inteiro; baixo &lt; 12, moderado de 12 a 24, elevado ≥ 25. Pesos e faixas são escolhas demonstrativas, não definidos pelo PDF.</p><p>Status operacional: menor SPI/CPI ≥ 0,95 é saudável; de 0,85 a 0,95 é atenção; abaixo de 0,85 é crítico. O radar é um sinal separado para investigar exposição.</p></section><section class="card"><div class="eyebrow">06 · SIMULAÇÃO & LIMITES</div><h3>Hipóteses para discussão do PMO</h3><div class="formula">Custo = orçamento × (1 + variação / 100)<br>Prazo = dias × (1 + variação / 100)</div><p>O cenário recalcula o índice ilustrativo sem alterar a base. Não há treinamento, inferência de machine learning ou acurácia validada. Para implantar a IA proposta, serão necessários histórico real validado, avaliação temporal, calibração, monitoramento e revisão humana.</p><p>O Dashboard soma valores e usa média simples do avanço. Fonte: vanguarda_pdf.pdf, Atividade 3, páginas 4–5. SPI/CPI, índice e seis projetos são recursos acrescentados para demonstrar o fluxo.</p></section></div>`}
function updateSim(){const p=projects.find(p=>p.id===document.querySelector('#sim-project').value),c=+document.querySelector('#cost').value,d=+document.querySelector('#delay').value;const sign=n=>(n>=0?'+':'')+n+'%';document.querySelector('#cost-label').textContent=sign(c);document.querySelector('#delay-label').textContent=sign(d);document.querySelector('#sim-result').innerHTML=`<div class="eyebrow" style="color:#bfdaa9">RESULTADO DO CENÁRIO</div><h3>${p.name}</h3><p class="subtitle">Custo total simulado</p><div class="result-number">${money(p.budget*(1+c/100))}</div><p>${money(Math.abs(p.budget*c/100))} ${c>=0?'acima':'abaixo'} do orçamento de ${money(p.budget)}.</p><hr><p class="subtitle">Prazo total simulado</p><div class="result-number">${Math.round(p.days*(1+d/100))} <small style="font-size:16px">dias</small></div><p>${Math.abs(Math.round(p.days*d/100))} dias ${d>=0?'a mais':'a menos'} em relação à base de ${p.days} dias.</p><hr><p class="subtitle">Radar ilustrativo · exposição no cenário</p><div class="result-number">${radar(p,c,d).score}<small style="font-size:16px">/100 · ${radar(p,c,d).level}</small></div><p>Base: ${radar(p).score}/100. O índice usa desvios, escopo e riscos abertos.</p><p>${radar(p,c,d).reasons.join(' · ')||'Sem sinal relevante pelas regras atuais.'}</p><hr><b>${c>20||d>20?'Impacto elevado no cenário':c>0||d>0?'Revisão de premissas sugerida':'Cenário de redução'}</b><p>Discuta viabilidade, capacidade de execução e riscos antes de rever a linha de base.</p>`}
function detail(id){const p=projects.find(p=>p.id===id);document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">${p.id} · DADOS DEMONSTRATIVOS</div><h1>${p.name}</h1>${badge(p)}<p>${p.sector} · Responsável fictício: ${p.owner}</p><div class="project-metrics"><div>Orçamento<h3>${money(p.budget)}</h3></div><div>Executado<h3>${money(p.spent)}</h3></div></div><div class="project-metrics"><div>SPI<h3>${(p.progress/p.planned).toFixed(2)}</h3></div><div>CPI<h3>${(p.budget*p.progress/100/p.spent).toFixed(2)}</h3></div><div>Prazo base<h3>${p.days} dias</h3></div></div><p>Avanço físico: ${p.progress}% · Planejado: ${p.planned}%</p><h3>Evidências do radar · ${radar(p).score}/100 (${radar(p).level})</h3><p>${radar(p).reasons.join(' · ')||'Sem sinal relevante pelas regras atuais.'}</p><p>${p.scope} alterações de escopo · ${p.openRisks} riscos abertos · ${p.history} projetos no histórico sintético.</p><p>Qualidade: ${p.validated?'registros sintéticos validados':'registros pendentes de validação; revisar despesas e andamento'}. O histórico é ilustrativo e não treina o radar.</p><h3>Risco monitorado</h3><p>${p.risk}</p><h3>Próxima ação sugerida</h3><p>${p.action}</p><p class="subtitle" style="margin:20px 0">Informações ilustrativas para avaliação do protótipo.</p>`;document.querySelector('dialog').showModal()}
function exportData(){const csv='\uFEFF'+['ID;Projeto;Setor;Status;Orçamento (R$ mi);Executado (R$ mi);Avanço (%);Prazo (dias);Dados',...projects.filter(p=>sector==='Todos os setores'||p.sector===sector).map(p=>`${p.id};${p.name};${p.sector};${p.status};${p.budget};${p.spent};${p.progress};${p.days};Demonstrativos`)].join('\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='vanguarda-portfolio-demonstrativo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){const page=location.hash.slice(1)||'dashboard',valid=['dashboard','projetos','simulador','metodologia'].includes(page)?page:'dashboard';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===valid);if(a.dataset.page===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#main').innerHTML=({dashboard,projetos:projectPage,simulador:simulator,metodologia:methodology}[valid])();document.querySelector('#sector')?.addEventListener('change',e=>{sector=e.target.value;render()});document.querySelector('#status')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});document.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;const start=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(start,start)});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelector('#export')?.addEventListener('click',exportData);if(valid==='simulador'){['sim-project','cost','delay'].forEach(id=>document.getElementById(id).addEventListener('input',updateSim));document.querySelector('#reset').onclick=()=>{document.querySelector('#cost').value=10;document.querySelector('#delay').value=15;updateSim()};updateSim()}}
window.addEventListener('hashchange',render);render();
